describe('Glacial Breath mob skill',function()
 it('enforces its Blood Weapon, facing, and flying gates and uses its Ice conal breath plan',function()
  local breath=require('scripts/actions/mobskills/glacial_breath');local move,adjust,process=xi.mobskills.mobBreathMove,utils.conalDamageAdjustment,xi.mobskills.processDamage;local params,damage=nil,nil;local blood,infront,animation=false,true,0;local mob={hasStatusEffect=function()return blood end,getAnimationSub=function()return animation end};local target={isInfront=function(_,other,angle)return other==mob and angle==128 and infront end,takeDamage=function(_,...)damage={...}end};assert(breath.onMobSkillCheck(target,mob,{})==0);blood=true;assert(breath.onMobSkillCheck(target,mob,{})==1);blood=false;infront=false;assert(breath.onMobSkillCheck(target,mob,{})==1);infront=true;animation=1;assert(breath.onMobSkillCheck(target,mob,{})==1);animation=0;xi.mobskills.mobBreathMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.BREATH,damageType=xi.damageType.ICE}end;utils.conalDamageAdjustment=function(_,_,_,value,amount)assert(value==123 and amount==.2);return 99 end;xi.mobskills.processDamage=function()return false end;assert(breath.onMobWeaponSkill(mob,target,{},{})==99);assert(params.percentMultipier==.083 and params.damageCap==1400 and params.bonusDamage==0 and params.mAccuracyBonus[1]==0 and params.mAccuracyBonus[2]==0 and params.mAccuracyBonus[3]==0 and params.resistStat==xi.mod.INT and params.element==xi.element.ICE and params.attackType==xi.attackType.BREATH and params.damageType==xi.damageType.ICE and params.shadowBehavior==xi.mobskills.shadowBehavior.IGNORE_SHADOWS and damage==nil);xi.mobskills.processDamage=function()return true end;breath.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobBreathMove,utils.conalDamageAdjustment,xi.mobskills.processDamage=move,adjust,process;assert(damage[1]==99 and damage[2]==mob and damage[3]==xi.attackType.BREATH and damage[4]==xi.damageType.ICE)
 end)
end)
